root=Path('D:/Codex/sd-research');dest=root/'repo/docs/SD-RESEARCH';c=json.loads((root/'lowpolyworks/catalogue.json').read_text('utf-8'));metrics=json.loads((dest/'data/lpw-measured-models.json').read_text('utf-8'));by={m['id']:m for m in metrics}
profiles=[
{'army':'warriors-of-chaos','title':'Chaos: the marks change the visual grammar of a shared base','observations':[
('Knight of Khorne · Axe and Knight of Khorne · Champion put the strongest red on the upright head crest, chest and weapon. Gold outlines separate these red fields from the dark hanging mail. Their outward shoulder spikes and near-rectangular crown forks make the upper silhouette read as a wide block with two vertical prongs. Both credit Vile Knight as their model base.','khorne-axe khorne-flail'),
('Knight of Nurgle, Heavy and Champion break that clean red-and-gold hierarchy with low-saturation olive plates, fleshy or mouth-like forms, irregular horns and much wider soft belly shapes. The credited sources explicitly include Ghoul/Abomination faces and a stone-deer statue for horns. A source object can therefore contribute its shape independently of the material painted on it.','nurgle-standard nurgle-heavy nurgle-champion'),
('Knight of Slaanesh · Axe and Lance retain the shared armoured base but the large purple cloth area, bright gold bands, tall delicate horn sweep and face-bearing shield make a different mark readable. The axe and lance variants share their major silhouette landmarks; the long lance adds reach without requiring a wholesale body redesign. Their total meshes are 2,504 and 2,366 triangles respectively.','slaanesh-axe slaanesh-lance'),
('Knight of Tzeentch · Sword/Lance and Warrior of Tzeentch use dark blue, cyan light, purple cloth and eyes as separate focal points. The visible eye animation is sourced from the Battle.net working animation texture series. The two knights each reference 30 eye-frame images; the warrior references 29. Counting those frames as unrelated painted materials exaggerates the number of visual ingredients.','tzeentch-sword tzeentch-lance warrior-of-tzeentch'),
('Knight Undivided · Sword/Lance and Aspiring Champion place black or charcoal plate beneath gold rims, horns and repeated star motifs. The palette creates a shared visual relationship without needing the red Khorne fields, green Nurgle flesh or cyan Tzeentch eyes. The credits separately name helmets, shoulder stars, horns and a fur cloak.','undivided-sword undivided-lance aspiring'),
('Warrior of Khorne · Cleaver is 1,009 triangles while Berserker is 1,930 and Bruiser is 1,720. The cleaver still reads as the same heavily armoured family in the published pictures. The large continuous red blade carries much of its identity; total triangle count is not a direct measure of how ornate a character reads.','warrior-of-khorne-cleaver warrior-of-khorne-berserker warrior-of-khorne')],
'limits':'These are observations of the 20 catalogue Chaos models. They do not establish a required Chaos triangle budget. The knight credits include mounted-base and horse sources, so each actual surface must be identified before interpreting an armour fragment as human anatomy.'},
{'army':'vampire-counts','title':'Vampire Counts: a faction built from deliberately different body types','observations':[
('Graveguard carries the undead identity with a concealed head, thin exposed bone, long polearm and ornate tall shield. Von Carstein Vampire and Von Carstein Dread Knight expose a pale face above upright plate and a long sword. Strigoi Vampire instead uses an enlarged muscular bare torso, long arms, claws and a dark animal-like face. Necrarch Vampire uses a hanging black robe and narrow exposed hands. These examples contradict a single universal vampire body proportion.','graveguard von-carstein von-carstein-dread-knight strigoi-vampire necrarch-vampire'),
('Von Carstein Vampire and Dread Knight both contain exactly 1,535 triangles, yet the catalogue has 30 versus 35 geosets and their files differ by 4,850 bytes. Their published images distinguish the cloth and armour treatment rather than a larger silhouette. Equal triangle totals therefore do not imply equal material partition or file contents.','von-carstein von-carstein-dread-knight'),
('Graveguard uses the Human campaign Footman, Human campaign tree, Undead inventory cover, Undead buildings and multiple creature sheets in one model. These are measured references in the actual MDX, not a list of suggested substitutes. Its credits name the shield as projected and the gargoyle head and helmet wings as Blizzard sources.','graveguard'),
('Blood Dragon concentrates red on the torso, shoulders and weapon while the limbs and hanging cloth stay dark. Its credited shoulder pads/breastplate come from a dragon-scale armour source, distinct from the skull belt, vampire face and helmet sources. In this collection the Blood Dragon silhouette is an armoured warrior, whereas the Strigoi silhouette is the body itself.','blood-dragon strigoi-vampire')],
'limits':'Only six Vampire Counts catalogue models are present. Skeleton ranks, cavalry formations and architecture cannot be inferred from this sample alone.'},
{'army':'the-empire','title':'Empire: equipment and heraldry carry role recognition','observations':[
('Empire Captain, Halberdier and Swordsman combine a bright red cloth area with pale breastplate, a dark boot mass and a feather or plume high on the head. Shields carry broad readable cross divisions. The polearm and sword separate the role while the torso palette keeps the figures together.','herrdave-86791 herrdave-88507 herrdave-86747'),
('Estalian Swordsman replaces the rectangular cross shield with a round concentric target, and Estalian Infantry/Spearman use a brimmed helmet rather than the same feathered profile. The distinctive equipment remains legible even though red, silver and brown remain shared colours.','herrdave-88509 herrdave-88510 herrdave-88508'),
('Knight of the Blazing Sun uses the head-sized gold sun crest as its strongest identifying motif in both mounted and dismounted versions. The dismounted model is 775 triangles; the mounted model is 1,713. The motif survives the much larger lower silhouette and is not dependent on adding tiny armour detail.','herrdave-84780 herrdave-84781'),
('Gluma’s four Empire Handgunners give the weapon a deliberately large visual footprint. The arquebus, flintlock, scoped and multi-barrel variants retain a compact human body, while barrel length, muzzle grouping and the sight create the visible differences. The catalogue totals span 526–598 triangles for these four models.',''),
('Human Cannon Bronze/Black and Human Mortar Bronze/Black share large wooden wheels, red hanging straps and a strongly outlined muzzle. The bronze/black variants have equal triangle counts within each pair (500 cannon, 482 mortar). The mortar changes the barrel angle and opening into a squat bowl-like shape, making function visible in silhouette.','')],
'limits':'The Empire collection includes 28 models, but no Empire buildings. The observations cover troops, heroes and artillery represented here; colour in the published pictures includes the chosen team colour.'},
{'army':'bretonnia','title':'Bretonnia: three commoners, not a knight-based faction sample','observations':[
('Bretonnian Archer, Pikeman and Swordsman share blue upper clothing, brown wrapped boots, a large square belt buckle and a small gold chest emblem. The archer has a hood, the pikeman a simple helmet, and the swordsman a tall blue shield; headgear and held equipment distinguish the three roles.','herrdave-124832 herrdave-124833 herrdave-124831'),
('The visible body proportions remain short-legged and broad-booted across the three published pictures. The pike extends far above the head, while the bow and shield create lateral rather than vertical mass. Their whole-model totals are 783, 825 and 896 triangles respectively. These are measured commoner examples, not a proposed generic humanoid budget.','herrdave-124832 herrdave-124833 herrdave-124831')],
'limits':'There are no Bretonnian knights, horses, nobles or buildings in this catalogue snapshot. A full Bretonnian silhouette profile would require additional permitted examples.'},
{'army':'dwarfs','title':'Dwarfs: artillery construction rather than humanoid proportions','observations':[
('Dwarf Cannon and all four Dwarf Organ Cannon versions use broad metal-covered wheels, low compact carriages, large muzzle openings, blue vertical bands and gold rings or face ornaments. The single cannon has one dominant barrel; the organ cannon has five aligned dark muzzles.','gluma-145021 gluma-145231 gluma-145232 gluma-145233 gluma-145234'),
('All four organ-cannon variants have exactly 878 triangles, 14 geosets and three catalogue geoset texture references. Their filenames and sequence variants describe different firing patterns, and their MDX sizes range from 184,277 to 322,173 bytes. This is a direct example of file size varying greatly without a triangle-count change.','gluma-145231 gluma-145232 gluma-145233 gluma-145234'),
('The Dwarf Cannon is 582 triangles. In the pictures, the organ version changes not only the barrel count but also the central vertical rib mass. The repeated five-muzzle silhouette makes the extra 296 triangles visually intelligible.','gluma-145021 gluma-145231')],
'limits':'All five Dwarf entries are artillery, and four are versions of one organ-cannon design. This set cannot support claims about dwarf body proportions, beards or infantry armour.'},
{'army':'skaven','title':'Skaven: hunched bodies, long tails and weapon-sized technology','observations':[
('Clanrat, Stormvermin, Warplock Jezzail and Ratling Gunner retain projecting snouts, bent-legged posture, thin segmented tails and small exposed feet. Green cloth ties the examples together while the body and hands remain a dirty brown or pale flesh colour.','gluma-80783 gluma-82593 gluma-80903 gluma-82702'),
('The Ratling Gunner’s back apparatus and multi-hole muzzle dominate the silhouette; its 1,890-triangle total is over twice the Clanrat’s 720. The Jezzail is between them at 1,085 triangles and emphasizes an exceptionally long firearm instead of a bulky pack. The examples show three different allocations of geometric effort to readable equipment.','gluma-82702 gluma-80783 gluma-80903'),
('Stormvermin raises the role with a broad upward-curving polearm blade, horned helmet and larger metal shoulder shape. Its 819 triangles remain much closer to Clanrat than to Ratling Gunner. The rank difference is concentrated in conspicuous extremities.','gluma-82593 gluma-80783'),
('Warp Lightning Cannon replaces the animal body with a low four-wheel machine, but repeats dirty metal, brown timber and green accents. The bright green stone or energy form at the muzzle gives the device a focal colour that the ordinary body palette does not supply.','gluma-145290')],
'limits':'Only the six listed troops and machine variants are represented. No Skaven buildings or large monsters are present in this snapshot.'},
{'army':'lizardmen','title':'Lizardmen: distinct reptile body families under a shared ornament vocabulary','observations':[
('Saurus Warrior and Oldblood use deep blue scale fields, cream horns and claws, gold fittings and a bright turquoise shield. Oldblood expands the head with a gold crest and large cheek shapes; the body remains recognizably the same heavy reptile family.','gluma-137328 gluma-140896'),
('Skink Worker, Spear Skink and Blowpipe Skink have much thinner lower legs, large round eyes, a narrow long tail and tall coloured head fins. The Worker is not a scaled-down Saurus: its eye and head-to-body relationship are visibly different.','gluma-134840 gluma-134398 gluma-134399'),
('Kroxigor and Ancient Kroxigor broaden the jaw, hands and upper torso. Both carry a heavy two-handed weapon across the body; the Ancient adds a tall geometric gold-and-turquoise crest. Their unit totals are 925 and 1,154 triangles.','gluma-146392 gluma-146394'),
('Cold One Rider puts a blue rider and turquoise shield over an olive-green mount, giving two bodies separate colour blocks. The Feral Cold One alone is 480 triangles; the rider unit is 1,492. This is a real mounted-versus-unmounted comparison within one authored pack.','gluma-143396 gluma-143398'),
('Blue and Orange Blowpipe Skink each have 753 triangles and an identical multiset of component shape fingerprints; Skink Skirmisher and Orange Skink Skirmisher each have 863 with the same result. Their published pictures differ strongly in skin colour. Shape reuse and palette variation are independently measurable here.','gluma-134399 gluma-134404 gluma-134400 gluma-134402'),
('Skink High Priest Hero and its Swimless version retain 954 triangles and matching component geometry. Removing six named Swim sequences reduces the file from 370,952 to 286,572 bytes. Skink Worker likewise keeps 776 triangles but loses 118,708 bytes with eleven Swim sequences absent. Animation scope is a major part of file weight.','gluma-135399 gluma-135400 gluma-134840 gluma-134841')],
'limits':'The 26 catalogue entries include hero/unit, colour and swimless variants; they are not 26 independent designs. The fingerprint comparison does not establish rig or animation identity.'},
{'army':'beastmen','title':'Beastmen: horns and hooves unify several levels of armour','observations':[
('Ungor Slave, Bowman and Spearman show the least armoured bodies: bare torsos, small horns, thin limbs and cloven feet. Gor Axe and Gor Flail enlarge the horns and add a round shield and shoulder metal. Bestigor adds taller spiked upper-body armour and banner-like vertical elements.',''),
('Gor Axe unit has 805 triangles and Gor Flail unit 851. Their body and round shield remain close in the pictures; the flexible chain weapon creates a new outline for an increase of 46 triangles. This is a small, concrete weapon-family variation rather than a broad blade budget.',''),
('Bray Shaman uses an animal skull-like head, long robe and a staff with two forked horn shapes. Bray Shaman of Tzeentch instead combines blue skin, purple hair, gold bands and a hooked gold staff. The Tzeentch unit is 716 triangles versus the ordinary Shaman unit’s 1,094; the mark remains readable without greater overall complexity.',''),
('Maximal’s Minotaur, Minotaur Drummer, Centigor Spearman and Centigor Axethrower add distinct body plans to the collection. The two centigors have four hoofed lower legs and an upright human-like torso, whereas the minotaurs remain bipedal with a greatly enlarged chest and horn span. The two centigor totals are 2,377 and 2,609 triangles.','')],
'limits':'The 20 entries contain many hero/unit pairs. Differences between Gluma and Maximal are not automatically faction rules; they are named authors’ interpretations within the same collection.'},
{'army':'dark-elves','title':'Dark Elves: pointed silhouettes and deliberately exposed pale skin','observations':[
('Witch Elf, Beastmaster and Slavemaster combine pale faces and arms with black or near-black clothing, purple vertical cloth and sharp triangular shoulder or head outlines. The Witch Elf uses white swept hair, broad curved swords and gold chest/shoulder trim; the Beastmaster uses dark studded shoulders and a coiled whip. The Slavemaster adds a gold horned crown and a taller pointed shoulder collar.','gluma-159912 gluma-160458 gluma-160460'),
('The hero/unit pairs change the glow and death presentation without needing a much larger visible body. Beastmaster Hero totals 580 triangles versus 602 for the unit; Saurus-style death-set comparison is explicit here too: the unit has Decay Bone and Decay Flesh, the hero has Dissipate. The hero’s sampled visible geometry is 578 versus the unit’s 562.','gluma-160458 gluma-160459'),
('Generic Ballista and Dark Elf Ballista keep the same basic crossbow-on-wheels layout. The Dark Elf version introduces upright blade-like prongs, purple limbs and heavier riveted wheel covers. Total geometry rises from 720 to 756 triangles. The equivalent bolt-thrower pair rises from 816 to 852, the same 36-triangle difference.','gluma-160790 gluma-160792 gluma-160791 gluma-160793')],
'limits':'These ten entries cover three character designs and four artillery variants. They do not include ordinary spear infantry, cavalry or buildings.'}
]
profiles.append({'army':'orcs-and-goblins','title':'Orcs and Goblins: mass and armour separate the represented roles','observations':[
('Snotling and Greenskin Savage Orc expose green torsos, outsized forearms, wide mouths with triangular teeth and short legs. The Savage Orc carries a pale spiked club; Snotling carries no weapon in the published pose. Their total meshes are 544 and 596 triangles.','herrdave-103868 herrdave-87374'),
('Greenskin Orc Boy uses a broad wooden shield and cleaver, with bright green accent shapes on the shield and upper body. Black Orc shifts the silhouette into a large closed helmet and a tall plated shield with a pale face-like emblem. Both preserve the large hand/weapon and short lower-body emphasis, but the material coverage changes the read from exposed muscle to solid armour.','herrdave-87375 herrdave-87376'),
('Black Orc Warboss adds a wide horned skull construction above the helmet and chains that descend from it. The hero and unit variants have 2,187 and 2,181 triangles respectively; the hero adds a green ground glow in the published image. That six-triangle difference is much smaller than the difference between Black Orc and Warboss (1,527 versus 2,181).','herrdave-87376 herrdave-87377 herrdave-104264'),
('Black Orc, both Warboss variants and Orc Boy map custom texture files under the same Greenskin collection, but each catalogue row has an explicit model-scoped texture mapping. Identical texture basenames cannot be resolved globally without checking those per-model mappings.','herrdave-87376 herrdave-87377 herrdave-104264 herrdave-87375')],
'limits':'The six entries do not cover mounted orcs, ordinary goblin troops, shamans, monsters or buildings. This is a profile of the represented Greenskin bodies and armour, not the entire army.'})
# Resolve references by exact observed model names when a visual comparison used several catalogue members.
name_refs={
('the-empire',3):['Empire Handgunners (Arquebus)','Empire Handgunners (Flintlock)','Empire Handgunners (Scoped)','Empire Handgunners'],
('the-empire',4):['Human Cannon Bronze','Human Cannon Black','Human Mortar Bronze','Human Mortar Black'],
('beastmen',0):['Ungor Slave','Ungor Bowman','Ungor with spear','Gor Axe (unit)','Gor Flail (unit)','Bestigor Unit'],
('beastmen',1):['Gor Axe (unit)','Gor Flail (unit)'],
('beastmen',2):['Bray Shaman Unit','Bray Shaman of Tzeentch Unit'],
('beastmen',3):['Minotaur','Minotaur Drummer','Centigor Spearman','Centigor Axethrower']}
for p in profiles:
 observations=[]
 for i,(text,ids)in enumerate(p['observations']):
  refs=['lpw-'+v for v in ids.split()]
  if (p['army'],i)in name_refs:refs=['lpw-'+m['id']for m in c if m['name']in name_refs[(p['army'],i)]]
  # Resolve the two Blazing Sun names using the exact current catalogue rather than remembered IDs.
  if p['army']=='the-empire' and i==2:refs=['lpw-'+m['id']for m in c if 'Blazing Sun'in m['name']]
  if not refs:raise ValueError('No source models: '+text)
  missing=[r for r in refs if r not in by]
  if missing:raise ValueError(missing)
  observations.append({'finding':text,'sourceModels':refs,'evidence':'downloaded published model thumbnails plus actual parsed MDX metrics and catalogue credit statements','certainty':'observed; bounded to these named examples'})
 p['observations']=observations
 rows=[m for m in c if m['army']==p['army']]
 lines=['# '+p['title'],'','Scope: '+str(len(rows))+' downloaded catalogue models. Visual evidence: `D:/Codex/sd-research/pictures/lowpolyworks/'+p['army']+'-*.jpg`; all four study-rendered angles and UV overlays are in `captures/models/<id>/`. These observations describe the examples, not mandatory style rules.','']
 for o in observations:lines +=[o['finding'],'','Sources: '+', '.join(by[v]['name']+' (`'+v+'`)'for v in o['sourceModels'])+'.','']
 lines+=['## Measured examples','','The visible column is the measured Stand-like sample recorded per model; total includes hidden and death-only geometry. Texture paths include effects and animated frames.','','| Model | Total triangles | Sample visible | Geosets | Texture paths | Bytes |','|---|---:|---:|---:|---:|---:|']
 for m in rows:
  d=by['lpw-'+m['id']];lines.append(f'| {m["name"]} | {d["triangles"]} | {d["sampleVisibleTriangles"]} | {d["geosets"]} | {d["textureReferences"]} | {d["bytes"]:,} |')
 lines +=['','## What this sample does not establish','',p['limits'],'']
 (dest/('subjects/lpw-faction-'+p['army']+'.md')).write_text('\n'.join(lines),'utf-8')
(dest/'data/lpw-faction-profiles.json').write_text(json.dumps(profiles,indent=2,ensure_ascii=False),'utf-8')
print(json.dumps({'profiles':len(profiles),'observations':sum(len(p['observations'])for p in profiles),'allModels':len(c)}))